#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/pm/device.h>
#include <zephyr/ztest.h>

/* Global state variables for devices */
static enum pm_device_state state_a;
static enum pm_device_state state_b;
static enum pm_device_state state_c;

/* Device PM action callbacks */
static int device_a_pm_action(const struct device *dev, enum pm_device_action action)
{
	switch (action) {
	case PM_DEVICE_ACTION_SUSPEND:
		zassert_equal(state_b, PM_DEVICE_STATE_SUSPENDED, "state_b not equal to PM_DEVICE_STATE_SUSPENDED");
		state_a = PM_DEVICE_STATE_SUSPENDED;
		break;
	case PM_DEVICE_ACTION_RESUME:
		state_a = PM_DEVICE_STATE_ACTIVE;
		break;
	default:
		return -ENOTSUP;
	}
	return 0;
}

static int device_b_pm_action(const struct device *dev, enum pm_device_action action)
{
	switch (action) {
	case PM_DEVICE_ACTION_SUSPEND:
		/* Assert that C was suspended before B */
		zassert_equal(state_c, PM_DEVICE_STATE_SUSPENDED,
			      "state_c not equal to PM_DEVICE_STATE_SUSPENDED");
		state_b = PM_DEVICE_STATE_SUSPENDED;
		break;
	case PM_DEVICE_ACTION_RESUME:
		state_b = PM_DEVICE_STATE_ACTIVE;
		break;
	default:
		return -ENOTSUP;
	}
	return 0;
}

static int device_c_pm_action(const struct device *dev, enum pm_device_action action)
{
	switch (action) {
	case PM_DEVICE_ACTION_SUSPEND:
		state_c = PM_DEVICE_STATE_SUSPENDED;
		break;
	case PM_DEVICE_ACTION_RESUME:
		state_c = PM_DEVICE_STATE_ACTIVE;
		break;
	default:
		return -ENOTSUP;
	}
	return 0;
}

/* Device definitions */
PM_DEVICE_DEFINE(device_a, device_a_pm_action);
PM_DEVICE_DEFINE(device_b, device_b_pm_action);
PM_DEVICE_DEFINE(device_c, device_c_pm_action);

/* Helper to get device pointer from PM_DEVICE_DEFINE */
#define GET_PM_DEVICE_PTR(name) (&__pm_device_##name)

/* Test setup and teardown */
static void test_pm_setup(void)
{
	state_a = PM_DEVICE_STATE_ACTIVE;
	state_b = PM_DEVICE_STATE_ACTIVE;
	state_c = PM_DEVICE_STATE_ACTIVE;

	/* Ensure devices are initially active */
	zassert_ok(pm_device_state_set(GET_PM_DEVICE_PTR(device_a), PM_DEVICE_STATE_ACTIVE));
	zassert_ok(pm_device_state_set(GET_PM_DEVICE_PTR(device_b), PM_DEVICE_STATE_ACTIVE));
	zassert_ok(pm_device_state_set(GET_PM_DEVICE_PTR(device_c), PM_DEVICE_STATE_ACTIVE));
}

/* Test case */
ZTEST(power_management_1cpu, test_device_order)
{
	/* Set up dependencies: B depends on C, A depends on B */
	zassert_ok(pm_device_children_set(GET_PM_DEVICE_PTR(device_b), GET_PM_DEVICE_PTR(device_c), true));
	zassert_ok(pm_device_children_set(GET_PM_DEVICE_PTR(device_a), GET_PM_DEVICE_PTR(device_b), true));

	/* Try to suspend device A (which should suspend B, then C) */
	zassert_ok(pm_device_state_set(GET_PM_DEVICE_PTR(device_a), PM_DEVICE_STATE_SUSPENDED));

	/* Verify final states */
	zassert_equal(state_a, PM_DEVICE_STATE_SUSPENDED);
	zassert_equal(state_b, PM_DEVICE_STATE_SUSPENDED);
	zassert_equal(state_c, PM_DEVICE_STATE_SUSPENDED);

	/* Resume devices */
	zassert_ok(pm_device_state_set(GET_PM_DEVICE_PTR(device_a), PM_DEVICE_STATE_ACTIVE));

	/* Verify final states */
	zassert_equal(state_a, PM_DEVICE_STATE_ACTIVE);
	zassert_equal(state_b, PM_DEVICE_STATE_ACTIVE);
	zassert_equal(state_c, PM_DEVICE_STATE_ACTIVE);
}

ZTEST_SUITE(power_management_1cpu, NULL, test_pm_setup, NULL, NULL, NULL);
